-- 0008: moderator sanctions (warnings, chat mutes, account bans) with history. Mirrors later-schema.js (n: 8).
CREATE TABLE IF NOT EXISTS sanctions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, kind TEXT NOT NULL, reason TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', until_at BIGINT, actor TEXT NOT NULL, report_ref TEXT, created_at BIGINT NOT NULL, lifted_at BIGINT, lifted_by TEXT);
CREATE INDEX IF NOT EXISTS ix_sanctions_user ON sanctions(user_id, id);
CREATE INDEX IF NOT EXISTS ix_sanctions_kind ON sanctions(kind, lifted_at);
